## Why This Is Asked
Tests ability to architect a simple, scalable UI state pattern with Context + useReducer, while handling real-time updates and preventing unnecessary re-renders. It also exercises memoization and debouncing—common patterns in feature-flag management UIs.

## Key Concepts
- React Context + useReducer for centralized state management
- React.memo for selective re-render optimization
- Debouncing external updates to reduce server load
- Clean-up on unmount to prevent memory leaks

## Code Example
```javascript
// FeatureFlagContext.tsx
import React, { createContext, useContext, useReducer, useEffect, useRef, useCallback } from 'react';

type Action =
  | { type: 'SET_FLAG'; name: string; value: boolean }
  | { type: 'PATCH_FLAGS'; patches: Record<string, boolean> };

type State = Record<string, boolean>;

const reducer = (state: State, action: Action): State => {
  switch (action.type) {
    case 'SET_FLAG':
      return { ...state, [action.name]: action.value };
    case 'PATCH_FLAGS':
      return { ...state, ...action.patches };
    default:
      return state;
  }
};

const FeatureFlagContext = createContext<{
  flags: State;
  dispatch: React.Dispatch<Action>;
} | null>(null);

// Debounce hook
const useDebounce = (callback: () => void, delay: number) => {
  const timeoutRef = useRef<NodeJS.Timeout>();
  const callbackRef = useRef(callback);

  useEffect(() => { callbackRef.current = callback; });

  useEffect(() => {
    return () => clearTimeout(timeoutRef.current);
  }, []);

  return useCallback(() => {
    clearTimeout(timeoutRef.current);
    timeoutRef.current = setTimeout(() => callbackRef.current(), delay);
  }, [delay]);
};

export const FeatureFlagProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [flags, dispatch] = useReducer(reducer, {});
  const debouncedUpdate = useDebounce(() => {
    // Push flag changes to server
    fetch('/api/flags', { method: 'PATCH', body: JSON.stringify(flags) });
  }, 200);

  useEffect(() => { debouncedUpdate(); }, [flags]);

  return (
    <FeatureFlagContext.Provider value={{ flags, dispatch }}>
      {children}
    </FeatureFlagContext.Provider>
  );
};

// Custom hook
export const useFeatureFlag = (name: string): [boolean, (value: boolean) => void] => {
  const { flags, dispatch } = useContext(FeatureFlagContext)!;
  const enabled = flags[name] ?? false;
  const setEnabled = useCallback((value: boolean) => {
    dispatch({ type: 'SET_FLAG', name, value });
  }, [name]);

  return [enabled, setEnabled];
};

// Debug Panel
const FlagRow = React.memo(({ name, value, onToggle }: { name: string; value: boolean; onToggle: () => void }) => (
  <div>
    <span>{name}</span>
    <button onClick={onToggle}>{value ? 'ON' : 'OFF'}</button>
  </div>
));

export const DebugPanel = ({ flags, dispatch }: { flags: State; dispatch: React.Dispatch<Action> }) => {
  return (
    <div>
      {Object.entries(flags).map(([name, value]) => (
        <FlagRow
          key={name}
          name={name}
          value={value}
          onToggle={() => dispatch({ type: 'SET_FLAG', name, value: !value })}
        />
      ))}
    </div>
  );
};
```

## Purpose
Tests the ability to implement offline-first, real-time collaboration with a patch-based DOM updater and proper sequencing. Covers DOM operations, fetch, WebSocket handling, Service Worker caching, and error handling with reconnection strategies.

## Key Concepts
- Patch-based DOM updates using small, immutable operations
- Per-cell sequencing and out-of-order patch buffering
- Offline-first architecture with Service Worker stale-while-revalidate
- Reconnection strategy with exponential backoff and jitter

## Code Example
```javascript
// REST/WS wrapper with reconnection
class GridClient {
  constructor(url) { this.url = url; this.ws = null; this.seq = {}; }
  async init() {
    const layout = await fetch(this.url + '/grid').then(r => r.json());
    this.render(layout);
    this.connect();
  }
  connect() {
    this.ws = new WebSocket(this.url.replace('http','ws') + '/stream');
    this.ws.onmessage = e => this.process(JSON.parse(e.data));
    this.ws.onclose = () => setTimeout(() => this.connect(), this.backoff());
  }
  backoff() { return Math.min(30000, (this.attempts || 1) * 1000 * (0.5 + Math.random())); }

  // Patch processor with buffering
  process(patch) {
    const { cellId, seq } = patch;
    if (!this.seq[cellId] || seq > this.seq[cellId]) this.pending[cellId]?.push(patch);
    while (this.pending[cellId]?.length) {
      const p = this.pending[cellId].sort((a,b) => a.seq - b.seq).shift();
      if (p.seq === this.seq[cellId] + 1) { this.apply(p); this.seq[cellId] = p.seq; }
    }
  }
  apply({cellId, op, value}) {
    const el = document.getElementById(cellId);
    if (op === 'set') el.textContent = value;
    else if (op === 'add') el.insertAdjacentHTML('beforeend', value);
    else if (op === 'del') el.remove();
  }
}
```

